import{_ as s,o as a,c as l,V as n}from"./chunks/framework.12adfae7.js";const h=JSON.parse('{"title":"MySQL 数据库引擎选择与SQL查询技巧","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/coding-learning-record/mysql.md","filePath":"blogs/coding-learning-record/mysql.md"}'),o={name:"blogs/coding-learning-record/mysql.md"},e=n(`<p>当然，以下是包含SQL习题的完整Markdown格式博客内容：</p><h1 id="mysql-数据库引擎选择与sql查询技巧" tabindex="-1">MySQL 数据库引擎选择与SQL查询技巧 <a class="header-anchor" href="#mysql-数据库引擎选择与sql查询技巧" aria-label="Permalink to &quot;MySQL 数据库引擎选择与SQL查询技巧&quot;">​</a></h1><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>本文详细讨论了MySQL数据库中的两种存储引擎：InnoDB和MyISAM，并提供了它们在事务支持、外键、索引结构、查询性能等方面的比较。同时，文章还介绍了SQL查询的多种技巧，包括聚合函数、开窗函数以及不同类型的JOIN操作。</p><h2 id="存储引擎比较" tabindex="-1">存储引擎比较 <a class="header-anchor" href="#存储引擎比较" aria-label="Permalink to &quot;存储引擎比较&quot;">​</a></h2><h3 id="innodb" tabindex="-1">InnoDB <a class="header-anchor" href="#innodb" aria-label="Permalink to &quot;InnoDB&quot;">​</a></h3><ul><li><strong>事务支持</strong>：支持完整的事务处理。</li><li><strong>外键</strong>：支持外键约束，有助于维护数据完整性。</li><li><strong>索引结构</strong>：使用B+树的聚集索引，数据按主键聚集存储。</li></ul><h3 id="myisam" tabindex="-1">MyISAM <a class="header-anchor" href="#myisam" aria-label="Permalink to &quot;MyISAM&quot;">​</a></h3><ul><li><strong>事务</strong>：不支持事务。</li><li><strong>外键</strong>：不支持外键。</li><li><strong>索引结构</strong>：使用B+树的非聚集索引，存储数据地址。</li><li><strong>查询性能</strong>：读取性能较好，写入和并发性能较弱。</li></ul><h2 id="sql查询技巧" tabindex="-1">SQL查询技巧 <a class="header-anchor" href="#sql查询技巧" aria-label="Permalink to &quot;SQL查询技巧&quot;">​</a></h2><h3 id="聚合函数" tabindex="-1">聚合函数 <a class="header-anchor" href="#聚合函数" aria-label="Permalink to &quot;聚合函数&quot;">​</a></h3><ul><li><code>SUM()</code>, <code>AVG()</code>, <code>MAX()</code>, <code>MIN()</code>, <code>COUNT()</code>：用于数据聚合计算。</li></ul><h3 id="开窗函数" tabindex="-1">开窗函数 <a class="header-anchor" href="#开窗函数" aria-label="Permalink to &quot;开窗函数&quot;">​</a></h3><ul><li><code>OVER()</code>, <code>PARTITION BY</code>：用于计算分组内的数据。</li></ul><h3 id="join操作" tabindex="-1">JOIN操作 <a class="header-anchor" href="#join操作" aria-label="Permalink to &quot;JOIN操作&quot;">​</a></h3><ul><li><code>INNER JOIN</code>：基于条件连接表。</li><li><code>LEFT JOIN</code>, <code>RIGHT JOIN</code>：包括左表或右表的所有行，加上满足条件的交集部分。</li><li><code>CROSS JOIN</code>：返回两个表的笛卡尔积。</li></ul><h2 id="sql习题及解答" tabindex="-1">SQL习题及解答 <a class="header-anchor" href="#sql习题及解答" aria-label="Permalink to &quot;SQL习题及解答&quot;">​</a></h2><h3 id="选择不重复的班级id和考试编号组合" tabindex="-1">选择不重复的班级ID和考试编号组合 <a class="header-anchor" href="#选择不重复的班级id和考试编号组合" aria-label="Permalink to &quot;选择不重复的班级ID和考试编号组合&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT DISTINCT</span><span style="color:#BABED8;"> class_id, exam_num </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student;</span></span></code></pre></div><p>此语句用于从<code>student</code>表中提取所有不重复的班级ID和考试编号的组合。</p><h3 id="学生信息排序" tabindex="-1">学生信息排序 <a class="header-anchor" href="#学生信息排序" aria-label="Permalink to &quot;学生信息排序&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;">, age, score </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span><span style="color:#F78C6C;">ORDER BY</span><span style="color:#BABED8;"> score </span><span style="color:#F78C6C;">DESC</span><span style="color:#BABED8;">, age </span><span style="color:#F78C6C;">ASC</span><span style="color:#BABED8;">;</span></span></code></pre></div><p>此语句用于选取<code>student</code>表中的姓名、年龄和分数，并首先按分数降序排序，分数相同的情况下按年龄升序排序。</p><h3 id="学生年龄等级划分" tabindex="-1">学生年龄等级划分 <a class="header-anchor" href="#学生年龄等级划分" aria-label="Permalink to &quot;学生年龄等级划分&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;">, </span></span>
<span class="line"><span style="color:#BABED8;">       </span><span style="color:#F78C6C;">CASE</span><span style="color:#BABED8;"> </span></span>
<span class="line"><span style="color:#BABED8;">           </span><span style="color:#F78C6C;">WHEN</span><span style="color:#BABED8;"> age </span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">60</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">THEN</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">老同学</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#BABED8;">           </span><span style="color:#F78C6C;">WHEN</span><span style="color:#BABED8;"> age </span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">20</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">THEN</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">年轻</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#BABED8;">           </span><span style="color:#F78C6C;">ELSE</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">小同学</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#BABED8;">       </span><span style="color:#F78C6C;">END</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> age_level </span></span>
<span class="line"><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span></span>
<span class="line"><span style="color:#F78C6C;">ORDER BY</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">ASC</span><span style="color:#BABED8;">;</span></span></code></pre></div><p>此语句用于根据学生的年龄将他们分为三个等级，并按姓名升序排列。</p><h3 id="学生年龄排序并截取信息" tabindex="-1">学生年龄排序并截取信息 <a class="header-anchor" href="#学生年龄排序并截取信息" aria-label="Permalink to &quot;学生年龄排序并截取信息&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;">, age </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span><span style="color:#F78C6C;">ORDER BY</span><span style="color:#BABED8;"> age </span><span style="color:#F78C6C;">ASC</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">LIMIT</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">1</span><span style="color:#BABED8;">, </span><span style="color:#F78C6C;">3</span><span style="color:#BABED8;">;</span></span></code></pre></div><p>此语句用于选取<code>student</code>表中按年龄升序排列的学生姓名和年龄，并且只返回第2到第3条记录。</p><h3 id="汇总学生成绩" tabindex="-1">汇总学生成绩 <a class="header-anchor" href="#汇总学生成绩" aria-label="Permalink to &quot;汇总学生成绩&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> </span></span>
<span class="line"><span style="color:#BABED8;">    </span><span style="color:#82AAFF;">SUM</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> total_score, </span></span>
<span class="line"><span style="color:#BABED8;">    </span><span style="color:#82AAFF;">AVG</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> avg_score, </span></span>
<span class="line"><span style="color:#BABED8;">    </span><span style="color:#82AAFF;">MAX</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> max_score, </span></span>
<span class="line"><span style="color:#BABED8;">    </span><span style="color:#82AAFF;">MIN</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> min_score </span></span>
<span class="line"><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student;</span></span></code></pre></div><p>此语句用于计算<code>student</code>表中学生成绩的总和、平均值、最大值和最小值。</p><h3 id="班级平均成绩" tabindex="-1">班级平均成绩 <a class="header-anchor" href="#班级平均成绩" aria-label="Permalink to &quot;班级平均成绩&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> class_id, </span><span style="color:#82AAFF;">AVG</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> avg_score </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span><span style="color:#F78C6C;">GROUP BY</span><span style="color:#BABED8;"> class_id;</span></span></code></pre></div><p>此语句用于计算<code>student</code>表中每个班级的平均成绩，并按班级编号分组。</p><h3 id="每个班级每次考试的总学生人数" tabindex="-1">每个班级每次考试的总学生人数 <a class="header-anchor" href="#每个班级每次考试的总学生人数" aria-label="Permalink to &quot;每个班级每次考试的总学生人数&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> class_id, exam_num, </span><span style="color:#82AAFF;">COUNT</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">*</span><span style="color:#BABED8;">) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> total_num </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span><span style="color:#F78C6C;">GROUP BY</span><span style="color:#BABED8;"> class_id, exam_num;</span></span></code></pre></div><p>此语句用于计算<code>student</code>表中每个班级每次考试的学生总数，并按班级编号和考试编号分组。</p><h3 id="班级总成绩超过150分" tabindex="-1">班级总成绩超过150分 <a class="header-anchor" href="#班级总成绩超过150分" aria-label="Permalink to &quot;班级总成绩超过150分&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> class_id, </span><span style="color:#82AAFF;">SUM</span><span style="color:#BABED8;">(score) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> total_score </span></span>
<span class="line"><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span></span>
<span class="line"><span style="color:#F78C6C;">GROUP BY</span><span style="color:#BABED8;"> class_id </span></span>
<span class="line"><span style="color:#F78C6C;">HAVING</span><span style="color:#BABED8;"> </span><span style="color:#82AAFF;">SUM</span><span style="color:#BABED8;">(score) </span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">150</span><span style="color:#BABED8;">;</span></span></code></pre></div><p>此语句用于找出<code>student</code>表中总成绩超过150分的班级，并显示这些班级的编号和总成绩。</p><h3 id="学生姓名和当前日期" tabindex="-1">学生姓名和当前日期 <a class="header-anchor" href="#学生姓名和当前日期" aria-label="Permalink to &quot;学生姓名和当前日期&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;">, </span><span style="color:#C792EA;">DATE</span><span style="color:#89DDFF;">()</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> 当前日期 </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student;</span></span></code></pre></div><p>此语句用于选取<code>student</code>表中的学生姓名和当前日期。</p><h3 id="筛选特定姓名的学生并展示大写姓名" tabindex="-1">筛选特定姓名的学生并展示大写姓名 <a class="header-anchor" href="#筛选特定姓名的学生并展示大写姓名" aria-label="Permalink to &quot;筛选特定姓名的学生并展示大写姓名&quot;">​</a></h3><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> id </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">id</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">, </span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">name</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">, </span><span style="color:#82AAFF;">UPPER</span><span style="color:#BABED8;">(</span><span style="color:#F78C6C;">name</span><span style="color:#BABED8;">) </span><span style="color:#F78C6C;">AS</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">upper_name</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> student </span><span style="color:#F78C6C;">WHERE</span><span style="color:#BABED8;"> </span><span style="color:#F78C6C;">name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">热dog</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">;</span></span></code></pre></div><p>此语句用于选取<code>student</code>表中姓名为&#39;热dog&#39;的学生的学号、姓名及其姓名的大写形式。</p><h2 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h2><h3 id="关闭mysql的strict-mode" tabindex="-1">关闭MySQL的Strict Mode <a class="header-anchor" href="#关闭mysql的strict-mode" aria-label="Permalink to &quot;关闭MySQL的Strict Mode&quot;">​</a></h3><ul><li><p>执行初始化数据库sql脚本，报错，编辑<code>my.ini</code>文件，注释掉或修改<code>sql-mode</code>配置。</p></li><li><p>解决的问题：</p><ul><li>严格模式（STRICT_MODE）：如果应用程序在开发过程中没有严格遵守数据库的约束和规则，可能会产生错误。关闭严格模式可以减少这类错误，使得开发和调试过程更加灵活。 兼容性问题：在某些情况下，应用程序可能需要与旧版本的数据库或不同的数据库系统兼容。通过调整SQL模式，可以模拟其他数据库系统的行为。 性能优化：在特定情况下，某些SQL模式可能会引入额外的检查和约束，这可能会影响性能。关闭或修改这些模式可以提高查询性能。</li><li>可能带来的问题： 数据完整性风险：关闭严格模式可能会绕过一些数据完整性检查，从而增加数据错误和不一致的风险。 违反ACID属性：事务的原子性、一致性、隔离性和持久性（ACID属性）是数据库事务处理的基础。关闭严格模式可能会影响这些属性，尤其是在事务处理中。</li><li>兼容性问题：如果应用程序依赖于MySQL的严格行为，关闭严格模式可能会导致不可预见的行为和错误。 维护难度增加：关闭严格模式可能会使得数据库的行为与预期不符，增加维护和调试的难度。</li></ul></li><li><p>正确解决方式： 统一sql版本</p></li></ul><h2 id="sql学习资源" tabindex="-1">SQL学习资源 <a class="header-anchor" href="#sql学习资源" aria-label="Permalink to &quot;SQL学习资源&quot;">​</a></h2><ul><li><a href="https://github.com/liyupi/sql-mother" target="_blank" rel="noreferrer">SQL学习资源</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>根据应用需求选择合适的存储引擎。InnoDB适合需要事务支持和外键约束的场景，而MyISAM适合对读取速度有高要求的场景。同时，掌握SQL查询技巧对于数据库操作至关重要。</p>`,54),p=[e];function t(c,r,i,y,d,B){return a(),l("div",null,p)}const D=s(o,[["render",t]]);export{h as __pageData,D as default};
